import{_ as t,o as e,c as a,ag as o}from"./chunks/framework.DaAXJYxM.js";const l=JSON.parse('{"title":"第47章 第一个","description":"","frontmatter":{},"headers":[],"relativePath":"第47章_第一个.md","filePath":"第47章_第一个.md"}'),_={name:"第47章_第一个.md"};function r(n,p,s,c,i,u){return e(),a("div",null,[...p[0]||(p[0]=[o('<h1 id="第47章-第一个" tabindex="-1">第47章 第一个 <a class="header-anchor" href="#第47章-第一个" aria-label="Permalink to &quot;第47章 第一个&quot;">​</a></h1><p>十二月十六号，她拿到预录取。</p><p>那天下午三点多，我正在图书馆三楼靠窗那一排坐着。手机在桌肚里震了一下。</p><p>我低头看。</p><p>她说：我拿到了。</p><p>后面跟着一张图。图上是几行外文字，中间有一处被荧光笔划过，画得很歪，一看就是手抖的时候画的。</p><p>她说，第一个告诉你。</p><p>我看着那五个字，坐在图书馆里，一动不动。</p><p>我那时候心里第一反应是高。</p><p>第二反应不是高。</p><p>第二反应是：她说的是第一个。</p><p>第一个不是&quot;唯一一个&quot;，也不是&quot;最后一个&quot;。</p><p>第一个的意思是，后面还有第二个人、第三个人、一沓人要被告知。</p><p>我只是被排在了前面。</p><p>我抬头看了一眼窗外。十二月的太阳很白，照在对面的楼上有反光。图书馆里有人在翻页，有人在小声说话。</p><p>我把手机按下去，打了两个字：恭喜。</p><p>打完我看着那两个字，觉得太轻了。</p><p>我又加了一句。</p><p>我说，你等了一年多。</p><p>她说，对。</p><p>她说，我昨天没睡着。</p><p>我说，今天呢。</p><p>她说，今天也没睡着。</p><p>我说，那现在呢。</p><p>她说，现在我在楼梯间。</p><p>我说，为什么在楼梯间。</p><p>她说，家里有人。</p><p>她说，我在楼梯间抽了半根烟。</p><p>我愣了。</p><p>我说，你抽烟。</p><p>她说，我上个月才开始抽。</p><p>她说，就在阳台上抽，抽完把味道散了再进去。</p><p>她说，我们家阳台有个缝，我把手放在那个缝里能感觉到风。</p><p>她说，我刚才在那儿站了二十分钟。</p><p>我说，你为什么现在才告诉我。</p><p>她隔了一会儿回。</p><p>她说，因为我不敢。</p><p>她说，我拿到的第一件事是想跟你说。</p><p>她说，第二件事是想抽一根。</p><p>她说，第三件事是我妈问我笑什么。</p><p>我说，你怎么说。</p><p>她说，我说没有。</p><p>她说，你看，我从初中就会说没有。</p><p>那天下午她从楼梯间出来，又上线一次，说她要开始填东西了。</p><p>然后她说了一句让我到今天都没法忘的话。</p><p>她说，英国呀。</p><p>我说，嗯。</p><p>她说，唉，以后难见咯。</p><p>我说，你自己说的要远一点。</p><p>她说，我说的远一点不是这个远。</p><p>她说，我那时候十四岁。</p><p>我说，你现在十九。</p><p>她说，十九也不行。</p><p>然后她说。</p><p>她说，我不想出国。</p><p>我看到这句话，手里的笔掉在卷子上。</p><p>我坐在那儿，把那句话读了四遍。</p><p>她拿到了她花了两年去换的东西，她说不想。</p><p>我说，那你为什么还考。</p><p>她说，因为所有人都以为我想。</p><p>她说，因为我妈替我说了两年。</p><p>她说，因为我不说就像不领情。</p><p>我说，那现在呢。</p><p>她说，现在拿到了，不能说风凉话。</p><p>她说，拿到了就得走。</p><p>我坐在那里，第一次有一个念头，很清楚的念头。</p><p>我想说，那你别走。</p><p>我一个字都没打。</p><p>我打的是：我等你。</p><p>打出来以后我自己看了一眼，觉得这句话太大了，大到我不配说。</p><p>我删了。</p><p>我又打：你先看看是什么学校。</p><p>我也删了。</p><p>最后我发出去的是：你今天吃了什么。</p><p>她隔了很久回。</p><p>她说，我胃疼，吃不下。</p><p>她说，你问这个干什么。</p><p>我说，我不知道该问什么。</p><p>她说，你以后想问什么就问什么。</p><p>她说，你别绕。</p><p>我说，我没绕。</p><p>她说，你现在就在绕。</p><p>我坐在那里，看着这一句。</p><p>因为她说得对。</p><p>从腊月到现在，她每一次把话说开，我都在旁边找别的事说。</p><p>她说，你有话就说。</p><p>我说，有。</p><p>她说，那你说。</p><p>我把手放在屏幕上。</p><p>那天下午图书馆里有人站起来收书包，拉链的声音很响。</p><p>我打了一句：我不想你去。</p><p>打完我看了一会儿。</p><p>我把这句删了。</p><p>我发出去的是：你饿着不行，去吃点东西。</p><p>那天晚上她没有上线。</p><p>第二天也没有。</p><p>第三天，她妈在旧号上发了一条给她的朋友，说孩子出去了，晚点回。</p><p>那天开始，到第二月的二月，中间四十几天，她一个字都没有。</p><p>很多年以后我想起那个下午，我一直知道我在哪一秒把它丢掉了。</p><p>就是她问我&quot;你有话就说&quot;，我说&quot;有&quot;，然后我说让她去吃东西的那一秒。</p><p>那四天我是怎么过的，我后来跟人讲过很多次，每一次说法都不一样。</p><p>真实的情况是：那四天我什么也没做。</p><p>我没有生气，没有慌，也没有去找她。</p><p>我做了一件很没用的事：我把她十二月十六号下午发给我的那张图，在手机上放大，又缩小，又放大。</p><p>那张纸上画得歪的那道荧光笔，我看了不下三十遍。</p><p>我看到第二天晚上，她说了一句话：我妈今天把我那个号上的头像换了。</p><p>我说，换成了什么。</p><p>她说，换成了一个很干净的校徽。</p><p>她说，她说这个号以后要正经用。</p><p>我说，那你以前那些东西呢。</p><p>她说，我备份了。</p><p>她说，她不知道我备份了。</p><p>我说，那你给我看看。</p><p>她说，不行。</p><p>我说，为什么。</p><p>她说，因为我现在拿出来，我就得解释我从哪儿来的。</p><p>那之后她说了一句很怪的话。</p><p>她说，以后这个东西我不上这个号说。</p><p>我说，那你说哪儿。</p><p>她说，以后再说。</p><p>那四天里我把一句话写了三次，一次也没发。</p><p>第一次我写的是：你不想去可以不去。</p><p>第二次我写的是：你说一句不想，我去跟家里说。</p><p>第三次我写的是：我陪你到车站，你不进那个门都行。</p><p>第三次那一段我打了十七个字。</p><p>我删的时候手很快。</p><p>快到我后来一直在想，为什么我删得那么熟练。</p><p>后来我跟沈聿提过一次这件事。</p><p>我说，如果你一个人跟你说她不想去，你怎么办。</p><p>沈聿看了我一会儿，说，她跟你说了？</p><p>我说，她没有。</p><p>他说，那就是她不想去，但她不想你替她拿主意。</p><p>我说，为什么。</p><p>他说，因为你替她拿了，她就得替你负责。</p><p>他说，她不想欠你。</p><p>那天晚上我坐在床上想了很久。</p><p>我那时候以为沈聿说得冷。</p><p>很多年以后我才知道，那是那一年里有人跟我说得最准的一句话。</p>',138)])])}const m=t(_,[["render",r]]);export{l as __pageData,m as default};
